:root {
  color-scheme: light dark;

  --p0seid0n-surface: light-dark(#F5F6F8, #121419);
  --p0seid0n-raised: light-dark(#FFFFFF, #1A1D24);
  --p0seid0n-ink: light-dark(#15181F, #ECEEF2);
  --p0seid0n-ink-muted: light-dark(#5B6270, #969CAA);
  --p0seid0n-ink-faint: light-dark(#A3A9B5, #5E6473);
  --p0seid0n-line: light-dark(#DDE1E7, #2A2E37);
  --p0seid0n-control: light-dark(#E7EAEF, #2B303A);
  --p0seid0n-download: light-dark(#2F6FE4, #5B8DEF);
  --p0seid0n-upload: light-dark(#C8731A, #C97C26);
  /* Derived, not taken from the reference palette: the upload colour is too light
     to carry surface-coloured text at 4.5:1, so it is mixed toward the ink. */
  --p0seid0n-danger: color-mix(in oklab, var(--p0seid0n-upload) 80%, var(--p0seid0n-ink));

  --p0seid0n-radius-control: 12px;
  --p0seid0n-radius-panel: 16px;
  --p0seid0n-radius-panel-lg: 20px;

  --p0seid0n-shadow-popup: 0 12px 32px -8px light-dark(rgba(26, 36, 34, 0.18), rgba(0, 0, 0, 0.6));
}

:root.light {
  color-scheme: light;
}

:root.dark {
  color-scheme: dark;
}

@theme inline {
  --color-surface: var(--p0seid0n-surface);
  --color-raised: var(--p0seid0n-raised);
  --color-ink: var(--p0seid0n-ink);
  --color-ink-muted: var(--p0seid0n-ink-muted);
  --color-ink-faint: var(--p0seid0n-ink-faint);
  --color-line: var(--p0seid0n-line);
  --color-control: var(--p0seid0n-control);
  --color-accent: var(--p0seid0n-download);
  --color-accent-alt: var(--p0seid0n-upload);
  --color-danger: var(--p0seid0n-danger);

  --radius-control: var(--p0seid0n-radius-control);
  --radius-panel: var(--p0seid0n-radius-panel);
  --radius-panel-lg: var(--p0seid0n-radius-panel-lg);

  --font-sans: var(--font-barlow, "Barlow"), system-ui, sans-serif;
  --font-condensed:
    var(--font-barlow-semi-condensed, "Barlow Semi Condensed"), var(--font-barlow, "Barlow"),
    system-ui, sans-serif;

  --shadow-popup: var(--p0seid0n-shadow-popup);
}

@keyframes p0seid0n-toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs))
}

import { cva } from 'class-variance-authority'

export type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger'
export type ButtonSize = 'sm' | 'md' | 'lg'

/**
 * Button surfaces follow the reference motif: an ink-filled primary, a control-grey
 * secondary, a transparent ghost, and the theme danger colour.
 */
export const buttonVariants = cva(
  [
    'relative isolate inline-flex shrink-0 select-none items-center justify-center gap-2 overflow-hidden',
    'whitespace-nowrap rounded-control font-medium',
    'outline-none focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-3 focus-visible:outline-ink',
    'transition-[background-color,color,border-color,box-shadow] duration-150 motion-reduce:transition-none',
    'disabled:cursor-default disabled:opacity-55 aria-disabled:cursor-default aria-disabled:opacity-55',
  ].join(' '),
  {
    variants: {
      variant: {
        primary:
          'bg-ink text-surface hover:bg-[color-mix(in_oklab,var(--color-ink)_86%,var(--color-surface))]',
        secondary:
          'bg-control text-ink hover:bg-[color-mix(in_oklab,var(--color-control)_92%,var(--color-ink))]',
        ghost: 'bg-transparent text-ink hover:bg-control',
        danger:
          'bg-danger text-surface hover:bg-[color-mix(in_oklab,var(--color-danger)_86%,var(--color-ink))]',
      } satisfies Record<ButtonVariant, string>,
      size: {
        sm: 'min-h-8 px-3 text-[13px]',
        md: 'min-h-11 px-6 text-[15px]',
        lg: 'min-h-13 px-8 text-[17px]',
      } satisfies Record<ButtonSize, string>,
    },
    defaultVariants: {
      variant: 'primary',
      size: 'md',
    },
  },
)

import { cva } from 'class-variance-authority'

export type BadgeVariant = 'neutral' | 'accent' | 'accent-alt' | 'outline'

/**
 * The raw download colour sits just below 4.5:1 against surface-coloured text in
 * light mode, so the label is mixed toward the ink instead of the background.
 */
const accentFill = 'bg-[color-mix(in_oklab,var(--color-accent)_88%,var(--color-ink))]'

export const badgeVariants = cva(
  'inline-flex items-center gap-1 rounded-[10px] px-2 py-0.5 text-[12px] font-medium whitespace-nowrap',
  {
    variants: {
      variant: {
        neutral: 'bg-control text-ink-muted',
        accent: `${accentFill} text-surface`,
        'accent-alt': 'bg-danger text-surface',
        outline: 'border border-line text-ink-muted',
      } satisfies Record<BadgeVariant, string>,
    },
    defaultVariants: {
      variant: 'neutral',
    },
  },
)

import { computed, inject, provide, type ComputedRef, type InjectionKey } from 'vue'

export type DialogBehaviour = {
  closeOnOutside: ComputedRef<boolean>
  closeOnEsc: ComputedRef<boolean>
}

export const dialogBehaviourKey: InjectionKey<DialogBehaviour> = Symbol('p0seid0n-dialog')

export type DialogBehaviourSource = {
  closeOnOutside: () => boolean
  closeOnEsc: () => boolean
}

/**
 * The source is a plain pair of getters rather than the props object: a destructured
 * or defaulted props proxy can resolve before `withDefaults` settles, which would
 * freeze the flags at their defaults.
 */
export function provideDialogBehaviour(source: DialogBehaviourSource): void {
  provide(dialogBehaviourKey, {
    closeOnOutside: computed(source.closeOnOutside),
    closeOnEsc: computed(source.closeOnEsc),
  })
}

const defaults: DialogBehaviour = {
  closeOnOutside: computed(() => true),
  closeOnEsc: computed(() => true),
}

/** Both flags stay true when DialogContent is used without a Dialog parent. */
export function useDialogBehaviour(): DialogBehaviour {
  return inject(dialogBehaviourKey, defaults)
}

import { inject, type InjectionKey } from 'vue'

export type ToastVariant = 'default' | 'success' | 'danger'

export type ToastAction = {
  label: string
  /** Called after the notification is dismissed. */
  onClick?: () => void
}

export type ToastOptions = {
  title: string
  description?: string
  variant?: ToastVariant
  /** Overrides the provider default, in milliseconds. Zero keeps it open. */
  duration?: number
  action?: ToastAction
  /** Identity used by `dismiss`; generated when omitted. */
  id?: string
}

export type ToastRecord = ToastOptions & {
  id: string
  variant: ToastVariant
  duration: number
}

export type ToastApi = {
  toast: (options: ToastOptions) => string
  dismiss: (id: string) => void
  dismissAll: () => void
}

export const toastKey: InjectionKey<ToastApi> = Symbol('p0seid0n-toast')

/**
 * Calling this outside a ToastProvider throws rather than silently dropping the
 * notification, so a missing provider surfaces during development.
 */
export function useToast(): ToastApi {
  const api = inject(toastKey, null)
  if (!api) {
    throw new Error('useToast() must be called inside a ToastProvider.')
  }
  return api
}

import { inject, provide, shallowRef, type InjectionKey, type Ref } from 'vue'
import type { ToastOptions, ToastRecord } from './context'

export type ToastStack = {
  items: Ref<ToastRecord[]>
  push: (options: ToastOptions, duration: number, max: number) => string
  dismiss: (id: string) => void
  dismissAll: () => void
}

export const toastStackKey: InjectionKey<ToastStack> = Symbol('p0seid0n-toast-stack')

/**
 * The stack lives outside the provider component so the viewport can read the same
 * reactive list without prop drilling through slots.
 */
export function createToastStack(): ToastStack {
  const items = shallowRef<ToastRecord[]>([])
  let sequence = 0

  function dismiss(id: string): void {
    items.value = items.value.filter((item) => item.id !== id)
  }

  function dismissAll(): void {
    items.value = []
  }

  function push(options: ToastOptions, duration: number, max: number): string {
    sequence += 1
    const id = options.id ?? `p0seid0n-toast-${sequence}`
    const record: ToastRecord = {
      ...options,
      id,
      variant: options.variant ?? 'default',
      duration: options.duration ?? duration,
    }

    // Re-pushing an id moves it to the top of the stack instead of duplicating it.
    const withoutDuplicate = items.value.filter((item) => item.id !== id)
    const next = [...withoutDuplicate, record]
    // The cap trims the oldest entries, so a burst keeps the most recent ones.
    items.value = next.slice(Math.max(0, next.length - max))
    return id
  }

  return { items, push, dismiss, dismissAll }
}

export function provideToastStack(stack: ToastStack): void {
  provide(toastStackKey, stack)
}

export function useToastStack(): ToastStack {
  const stack = inject(toastStackKey, null)
  if (!stack) {
    throw new Error('ToastProvider is required to render notifications.')
  }
  return stack
}

/**
 * Bar geometry, ported from the reference PingStrip: each bar fills 0.6 of its
 * slot and the rest is the gap to its neighbours.
 */
const BAR = 0.6
/** A value this many times the median already reaches the top, so spikes cannot flatten the rest. */
const SPIKE = 3
/** Below this many samples the median is not meaningful, so the max is used instead. */
const MIN_SAMPLES_FOR_MEDIAN = 3

export function median(values: readonly number[]): number {
  const sorted = [...values].sort((a, b) => a - b)
  const mid = sorted.length >> 1
  return sorted.length % 2 === 0 ? (sorted[mid - 1] + sorted[mid]) / 2 : sorted[mid]
}

/**
 * Upper bound for the value axis. The reference clamps to `median * 3` so a few
 * spikes do not squash the rest; with one or two samples the median is too noisy,
 * so it falls back to the max (005 risk table).
 */
export function scaleTop(values: readonly number[]): number {
  if (values.length === 0) return 1
  const max = Math.max(...values)
  if (values.length < MIN_SAMPLES_FOR_MEDIAN) return Math.max(1, max)
  return Math.max(1, Math.min(max, median(values) * SPIKE))
}

export type SparklineOptions = {
  values: readonly number[]
  /** Values are laid out across this many slots; the newest sits at the right edge. */
  slots?: number
  /** Upper bound of the value axis; defaults to the derived scale. */
  max?: number
}

/**
 * Builds the bar path in a `0 0 slots 1` viewBox where y grows downward, so every
 * bar is drawn from y=1 up to `1 - value / top`. Returns an empty string when there
 * is nothing to draw.
 */
export function sparklinePath({ values, slots, max }: SparklineOptions): string {
  if (values.length === 0) return ''

  // The slot count never drops below the sample count, or bars would overlap.
  const width = Math.max(slots ?? values.length, values.length)
  const top = max !== undefined ? Math.max(1e-9, max) : scaleTop(values)
  const first = width - values.length
  const halfGap = (1 - BAR) / 2

  let d = ''
  for (let index = 0; index < values.length; index += 1) {
    const ratio = Math.min(1, Math.max(0, values[index] / top))
    const x = first + index + halfGap
    d += `M${round(x)},1V${round(1 - ratio)}h${BAR}V1Z`
  }
  return d
}

/** Trims float noise so the generated `d` stays comparable between runs. */
function round(value: number): number {
  return Math.round(value * 1000) / 1000
}

export type ThemeChoice = 'system' | 'light' | 'dark'
export type ResolvedTheme = 'light' | 'dark'

export const DEFAULT_STORAGE_KEY = 'p0seid0n-theme'

/** Reads the stored choice; anything unrecognised falls back to `system`. */
export function readStoredTheme(storageKey: string): ThemeChoice {
  try {
    const stored = localStorage.getItem(storageKey)
    if (stored === 'light' || stored === 'dark') return stored
  } catch {
    // Storage can be blocked (private mode, third-party context); system is the safe answer.
  }
  return 'system'
}

export function systemTheme(): ResolvedTheme {
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
}

/**
 * The class on `html` is the only thing the stylesheet reads. `system` removes both
 * classes so `color-scheme: light dark` keeps following the OS, which a pinned class
 * would stop doing.
 */
export function applyThemeToDocument(choice: ThemeChoice, attribute: string): ResolvedTheme {
  const root = document.documentElement
  root.classList.remove('light', 'dark')
  const resolved: ResolvedTheme = choice === 'system' ? systemTheme() : choice
  if (choice !== 'system') root.classList.add(choice)
  // The attribute mirrors the explicit choice for selectors that need it; `system`
  // omits it so styles can tell "unset" apart from a pinned light.
  if (choice === 'system') root.removeAttribute(attribute)
  else root.setAttribute(attribute, choice)
  return resolved
}

/**
 * Inline this in `<head>` before the app bundle so a stored choice paints on the
 * first frame. It touches only `<html>` and never the framework state, so there is
 * nothing for hydration to disagree with.
 */
export function themeScript(
  storageKey: string = DEFAULT_STORAGE_KEY,
  attribute: string = 'data-theme',
): string {
  return `(()=>{try{var r=document.documentElement,k=${JSON.stringify(storageKey)},a=${JSON.stringify(attribute)},s=localStorage.getItem(k);r.classList.remove("light","dark");if(s==="light"||s==="dark"){r.classList.add(s);r.setAttribute(a,s)}else{r.removeAttribute(a)}}catch(e){}})()`
}

import { inject, type InjectionKey, type Ref } from 'vue'
import { DEFAULT_STORAGE_KEY, type ResolvedTheme, type ThemeChoice } from './theme'

export type ThemeApi = {
  /** The stored choice: system, light or dark. */
  theme: Ref<ThemeChoice>
  /** What is actually painted right now. */
  resolvedTheme: Ref<ResolvedTheme>
  setTheme: (choice: ThemeChoice) => void
  systemTheme: () => ResolvedTheme
  storageKey: string
}

export const themeKey: InjectionKey<ThemeApi> = Symbol('p0seid0n-theme')

export function useTheme(): ThemeApi {
  const api = inject(themeKey, null)
  if (!api) {
    throw new Error('useTheme() must be called inside a ThemeProvider.')
  }
  return api
}

export { DEFAULT_STORAGE_KEY }
